-- -------------------------------------------------------------
-- ISSystem データベース定義スキーマ (PostgreSQL 版 / 仕様書 v2.1.0)
-- -------------------------------------------------------------
-- ※ PostgreSQL では PRAGMA は使用しない（外部キー制約は常に有効）
-- ※ DATETIME → TIMESTAMP, AUTOINCREMENT → GENERATED BY DEFAULT AS IDENTITY
-- ※ INSERT OR IGNORE → INSERT ... ON CONFLICT DO NOTHING
-- ※ server TIME ZONE は Asia/Tokyo（CURRENT_TIMESTAMP は JST 時刻で格納される）

-- 1. 教職員アカウント (users)
CREATE TABLE IF NOT EXISTS users (
  id TEXT PRIMARY KEY,
  staff_code TEXT UNIQUE NOT NULL,
  name TEXT NOT NULL,
  email TEXT UNIQUE,
  password_hash TEXT NOT NULL,
  role TEXT NOT NULL DEFAULT 'TEACHER',
  grade TEXT,
  department TEXT,
  extension_number TEXT,
  avatar_url TEXT,
  created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
  updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
);
CREATE INDEX IF NOT EXISTS idx_users_role ON users(role);
CREATE INDEX IF NOT EXISTS idx_users_department ON users(department);

-- 1b. 教務フラグと招待コード発行者 (後続マイグレーション対応)
ALTER TABLE users ADD COLUMN IF NOT EXISTS is_kyomu INTEGER NOT NULL DEFAULT 0;
ALTER TABLE users ADD COLUMN IF NOT EXISTS invited_by_user_id TEXT REFERENCES users(id) ON DELETE SET NULL;

-- 1c. 自主分散招待コード (invitation_codes)
CREATE TABLE IF NOT EXISTS invitation_codes (
  id TEXT PRIMARY KEY,
  code TEXT UNIQUE NOT NULL,
  created_by_user_id TEXT NOT NULL,
  used_by_user_id TEXT,
  used_for TEXT,
  is_used INTEGER NOT NULL DEFAULT 0,
  expires_at TIMESTAMP NOT NULL,
  created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
  FOREIGN KEY (created_by_user_id) REFERENCES users(id) ON DELETE CASCADE,
  FOREIGN KEY (used_by_user_id) REFERENCES users(id) ON DELETE SET NULL
);
CREATE INDEX IF NOT EXISTS idx_invitation_code ON invitation_codes(code);
CREATE INDEX IF NOT EXISTS idx_invitation_expires ON invitation_codes(expires_at);
-- 招待コードは発行時点で利用目的 (REGISTER / PASSWORD_RESET) が確定しないため、消費時に記録する
ALTER TABLE invitation_codes ADD COLUMN IF NOT EXISTS used_for TEXT;

-- 2. 掲示板・回覧板投稿 (posts)
CREATE TABLE IF NOT EXISTS posts (
  id TEXT PRIMARY KEY,
  title TEXT NOT NULL,
  content TEXT NOT NULL,
  author_id TEXT NOT NULL,
  target_scope TEXT DEFAULT '{"grade":"ALL","department":"ALL"}',
  attachments TEXT DEFAULT '[]',
  display_start_date DATE,
  display_end_date DATE,
  is_deleted INTEGER DEFAULT 0,
  posted_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
  created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
  updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
  FOREIGN KEY (author_id) REFERENCES users(id) ON DELETE CASCADE
);
-- 既存データベースに対するマイグレーション (投稿日時・添付ファイル・掲示期間)
ALTER TABLE posts ADD COLUMN IF NOT EXISTS posted_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP;
-- 掲示期間（掲示開始日・掲示終了日とも任意。未設定時は投稿日が掲示開始日、終了日未設定は「期間限定の掲示ではない」）
ALTER TABLE posts ADD COLUMN IF NOT EXISTS display_start_date DATE;
ALTER TABLE posts ADD COLUMN IF NOT EXISTS display_end_date DATE;
-- 対象日（掲示が日別表示で所属する日。投稿フォームの「対象日」を保存する）
ALTER TABLE posts ADD COLUMN IF NOT EXISTS target_date DATE;
-- 既存レコードの冪等バックフィル：対象日未設定の投稿は投稿日を対象日へ補完（TIMESTAMP の壁時計を DATE へキャスト）
UPDATE posts SET target_date = CAST(to_char(COALESCE(posted_at, created_at), 'YYYY-MM-DD') AS DATE)
WHERE target_date IS NULL;
-- 区分・優先度は撤廃（カテゴリフィルタの廃止に伴いカラムを削除）
ALTER TABLE posts DROP COLUMN IF EXISTS post_type;
ALTER TABLE posts DROP COLUMN IF EXISTS priority;
-- 論理削除フラグは INTEGER (0/1) に統一 (DB スキーマ統一の完結)
-- 旧 boolean 環境からの冪等マイグレーション。型統一済み環境では失敗し、ensureSchema は警告扱いとする
-- boolean 型インデックス idx_posts_deleted が型変換を妨げるため、先に DROP → 型変換 → 再作成する
-- ※ USING は integer 値を自己キャストで維持する。「true/false 以外は 0」だと毎回テーブルを書き換えて
--    is_deleted=1 が 0 に巻き戻る（サーバ再起動で論理削除レコードが復活していた）ため、旧パターンは使わない
DROP INDEX IF EXISTS idx_posts_deleted;
ALTER TABLE posts ALTER COLUMN is_deleted DROP DEFAULT;
ALTER TABLE posts ALTER COLUMN is_deleted TYPE integer USING (CASE WHEN is_deleted::text = 'true' THEN 1 WHEN is_deleted::text = 'false' THEN 0 WHEN is_deleted::text = '1' THEN 1 WHEN is_deleted::text = '0' THEN 0 ELSE is_deleted::text::integer END);
ALTER TABLE posts ALTER COLUMN is_deleted SET DEFAULT 0;
CREATE INDEX IF NOT EXISTS idx_posts_deleted ON posts(is_deleted);

CREATE INDEX IF NOT EXISTS idx_posts_author ON posts(author_id);
CREATE INDEX IF NOT EXISTS idx_posts_deleted ON posts(is_deleted);
CREATE INDEX IF NOT EXISTS idx_posts_posted_at ON posts(posted_at);
CREATE INDEX IF NOT EXISTS idx_posts_target_date ON posts(target_date);
CREATE INDEX IF NOT EXISTS idx_posts_display_start ON posts(display_start_date);
CREATE INDEX IF NOT EXISTS idx_posts_display_end ON posts(display_end_date);

-- 3b. 掲示板添付ファイル (bulletin_attachments)
CREATE TABLE IF NOT EXISTS bulletin_attachments (
  id TEXT PRIMARY KEY,
  post_id TEXT,
  original_name TEXT NOT NULL,
  stored_name TEXT NOT NULL,
  mime_type TEXT,
  extension TEXT,
  size_bytes BIGINT DEFAULT 0,
  uploaded_by TEXT,
  created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
);
CREATE INDEX IF NOT EXISTS idx_attachment_post ON bulletin_attachments(post_id);
CREATE INDEX IF NOT EXISTS idx_attachment_uploader ON bulletin_attachments(uploaded_by);

-- 3c. 掲示板コメント (bulletin_comments)
-- 投稿者への補足・確認コメント。右ペインでその場で送信し、永続化して詳細取得で返す。
-- 投稿者名は users と JOIN して補正するため author_name は自己完結の履歴値、FK は投稿のみ（作者削除でコメントは残す）。
CREATE TABLE IF NOT EXISTS bulletin_comments (
  id TEXT PRIMARY KEY,
  post_id TEXT NOT NULL,
  author_id TEXT NOT NULL,
  author_name TEXT NOT NULL,
  comment_text TEXT NOT NULL,
  created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
  FOREIGN KEY (post_id) REFERENCES posts(id) ON DELETE CASCADE
);
CREATE INDEX IF NOT EXISTS idx_bulletin_comment_post ON bulletin_comments(post_id);
CREATE INDEX IF NOT EXISTS idx_bulletin_comment_author ON bulletin_comments(author_id);

-- 3. 回覧板承認・既読ログ (post_acknowledgements)
CREATE TABLE IF NOT EXISTS post_acknowledgements (
  id TEXT PRIMARY KEY,
  post_id TEXT NOT NULL,
  user_id TEXT NOT NULL,
  status TEXT NOT NULL DEFAULT 'UNREAD',
  comment TEXT,
  acknowledged_at TIMESTAMP,
  FOREIGN KEY (post_id) REFERENCES posts(id) ON DELETE CASCADE,
  FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE,
  UNIQUE (post_id, user_id)
);
CREATE INDEX IF NOT EXISTS idx_ack_post_user ON post_acknowledgements(post_id, user_id);
CREATE INDEX IF NOT EXISTS idx_ack_user_status ON post_acknowledgements(user_id, status);

-- 4. 職員チャットチャンネル (chat_channels)
CREATE TABLE IF NOT EXISTS chat_channels (
  id TEXT PRIMARY KEY,
  name TEXT NOT NULL,
  type TEXT NOT NULL DEFAULT 'PUBLIC',
  members TEXT DEFAULT '[]',
  created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
);
CREATE INDEX IF NOT EXISTS idx_channels_type ON chat_channels(type);

-- 4b. チャンネル参加者 (実装互換用)
CREATE TABLE IF NOT EXISTS chat_channel_members (
  channel_id TEXT NOT NULL,
  user_id TEXT NOT NULL,
  is_hidden INTEGER DEFAULT 0,
  joined_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (channel_id, user_id),
  FOREIGN KEY (channel_id) REFERENCES chat_channels(id) ON DELETE CASCADE,
  FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE
);

-- 5. チャットメッセージ (chat_messages)
CREATE TABLE IF NOT EXISTS chat_messages (
  id TEXT PRIMARY KEY,
  channel_id TEXT NOT NULL,
  sender_id TEXT NOT NULL,
  message TEXT NOT NULL,
  meta_data TEXT DEFAULT '{}',
  is_cancelled INTEGER DEFAULT 0,
  cancelled_at TIMESTAMP,
  created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
  FOREIGN KEY (channel_id) REFERENCES chat_channels(id) ON DELETE CASCADE,
  FOREIGN KEY (sender_id) REFERENCES users(id) ON DELETE CASCADE
);
CREATE INDEX IF NOT EXISTS idx_chat_channel_time ON chat_messages(channel_id, created_at ASC);

-- メッセージ取り消し (is_cancelled)
-- 取り消し後は行を残し「取り消された」状態だけを保持する。本文 (message) は
-- サーバー側に残すが、クライアントとの通信（履歴取得・リアルタイム通知）には一切載せない。
-- 投稿時間 created_at は取り消し前の送信時刻のまま変更しない。
ALTER TABLE chat_messages ADD COLUMN IF NOT EXISTS is_cancelled INTEGER DEFAULT 0;
ALTER TABLE chat_messages ADD COLUMN IF NOT EXISTS cancelled_at TIMESTAMP;
CREATE INDEX IF NOT EXISTS idx_chat_cancelled ON chat_messages(channel_id, is_cancelled);

-- 5b. チャットメッセージ既読ログ (chat_message_reads)
-- 「誰が・どのメッセージを・いつ既読したか」を記録し、未読者一覧と未読バッジ数を算出する
CREATE TABLE IF NOT EXISTS chat_message_reads (
  channel_id TEXT NOT NULL,
  message_id TEXT NOT NULL,
  user_id TEXT NOT NULL,
  read_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (channel_id, message_id, user_id),
  FOREIGN KEY (channel_id) REFERENCES chat_channels(id) ON DELETE CASCADE,
  FOREIGN KEY (message_id) REFERENCES chat_messages(id) ON DELETE CASCADE,
  FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE
);
CREATE INDEX IF NOT EXISTS idx_chat_reads_channel ON chat_message_reads(channel_id, user_id);

-- 6. 職員室リアルタイム座席・在席状態 (seating_status)
CREATE TABLE IF NOT EXISTS seating_status (
  id TEXT PRIMARY KEY,
  user_id TEXT UNIQUE NOT NULL,
  desk_number TEXT NOT NULL,
  group_zone TEXT NOT NULL DEFAULT 'staff',
  current_status TEXT NOT NULL DEFAULT 'PRESENT',
  status_note TEXT DEFAULT '',
  updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
  FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE
);
CREATE INDEX IF NOT EXISTS idx_seating_zone ON seating_status(group_zone);
CREATE INDEX IF NOT EXISTS idx_seating_status ON seating_status(current_status);

-- 6b. 座席表マトリクス (seat_matrices / seat_matrix_cells)
-- rows/cols は 1..100。初期状態はセル無し＝誰のカードもないマトリクス。
CREATE TABLE IF NOT EXISTS seat_matrices (
  id TEXT PRIMARY KEY,
  name TEXT NOT NULL DEFAULT '座席表',
  rows INTEGER NOT NULL DEFAULT 5,
  cols INTEGER NOT NULL DEFAULT 6,
  updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
);
CREATE TABLE IF NOT EXISTS seat_matrix_cells (
  id TEXT PRIMARY KEY,
  matrix_id TEXT NOT NULL,
  row_idx INTEGER NOT NULL,
  col_idx INTEGER NOT NULL,
  user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
  UNIQUE (matrix_id, row_idx, col_idx),
  UNIQUE (matrix_id, user_id),
  CONSTRAINT chk_seat_matrix_row CHECK (row_idx BETWEEN 1 AND 100),
  CONSTRAINT chk_seat_matrix_col CHECK (col_idx BETWEEN 1 AND 100)
);
CREATE INDEX IF NOT EXISTS idx_seat_matrix_cells ON seat_matrix_cells(matrix_id, row_idx, col_idx);

-- 7. 施設・備品マスター (resources)
CREATE TABLE IF NOT EXISTS resources (
  id TEXT PRIMARY KEY,
  name TEXT NOT NULL,
  category TEXT NOT NULL DEFAULT 'ROOM',
  sort_order INTEGER
);
-- 表示順 (教務部がマスタ管理で ▲▼ 入れ替え。sort_order 未設定 (NULL) は category, name 順で末尾扱い)
ALTER TABLE resources ADD COLUMN IF NOT EXISTS sort_order INTEGER;

-- 8. 施設・備品予約記録 (reservations)
CREATE TABLE IF NOT EXISTS reservations (
  id TEXT PRIMARY KEY,
  resource_id TEXT NOT NULL,
  facility_id TEXT,
  user_id TEXT,
  user_name TEXT DEFAULT '教員',
  title TEXT NOT NULL,
  target_date TEXT,
  start_time TEXT NOT NULL,
  end_time TEXT NOT NULL,
  is_cancelled INTEGER DEFAULT 0,
  created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
  FOREIGN KEY (resource_id) REFERENCES resources(id),
  FOREIGN KEY (user_id) REFERENCES users(id)
);
CREATE INDEX IF NOT EXISTS idx_res_target_date ON reservations(target_date);
CREATE INDEX IF NOT EXISTS idx_res_resource ON reservations(resource_id, start_time, end_time);
CREATE INDEX IF NOT EXISTS idx_res_cancelled ON reservations(is_cancelled);
-- キャンセルフラグは INTEGER (0/1) に統一 (DB スキーマ統一の完結)
-- boolean 型インデックス idx_res_cancelled が型変換を妨げるため、先に DROP → 型変換 → 再作成する
DROP INDEX IF EXISTS idx_res_cancelled;
ALTER TABLE reservations ALTER COLUMN is_cancelled DROP DEFAULT;
ALTER TABLE reservations ALTER COLUMN is_cancelled TYPE integer USING (CASE WHEN is_cancelled::text = 'true' THEN 1 WHEN is_cancelled::text = 'false' THEN 0 WHEN is_cancelled::text = '1' THEN 1 WHEN is_cancelled::text = '0' THEN 0 ELSE NULL END);
ALTER TABLE reservations ALTER COLUMN is_cancelled SET DEFAULT 0;
CREATE INDEX IF NOT EXISTS idx_res_cancelled ON reservations(is_cancelled);

-- 9. 校内スケジュール・年間行事 (school_schedules)
CREATE TABLE IF NOT EXISTS school_schedules (
  id TEXT PRIMARY KEY,
  title TEXT NOT NULL,
  description TEXT DEFAULT '',
  event_date TEXT NOT NULL,
  start_time TEXT,
  end_time TEXT,
  category TEXT NOT NULL DEFAULT 'EVENT',
  target_grade INTEGER,
  created_by_user_id TEXT,
  created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
  updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
);
CREATE INDEX IF NOT EXISTS idx_schedules_date ON school_schedules(event_date);
CREATE INDEX IF NOT EXISTS idx_schedules_grade ON school_schedules(target_grade);

-- 10. 操作・監査ログ (audit_logs) ※ 90日保持 (cron Maintenance)
CREATE TABLE IF NOT EXISTS audit_logs (
  id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  user_id TEXT,
  user_name TEXT,
  action TEXT NOT NULL,
  resource_type TEXT,
  resource_id TEXT,
  old_value TEXT,
  new_value TEXT,
  ip_address TEXT,
  user_agent TEXT,
  created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP
);
CREATE INDEX IF NOT EXISTS idx_audit_created ON audit_logs(created_at DESC);
CREATE INDEX IF NOT EXISTS idx_audit_user ON audit_logs(user_id);
CREATE INDEX IF NOT EXISTS idx_audit_action ON audit_logs(action);
CREATE INDEX IF NOT EXISTS idx_audit_resource ON audit_logs(resource_type, resource_id);

-- 10. 簡易決裁・承認申請 (approvals)
CREATE TABLE IF NOT EXISTS approvals (
  id TEXT PRIMARY KEY,
  title TEXT NOT NULL,
  category TEXT NOT NULL DEFAULT 'PURCHASE',
  description TEXT,
  amount NUMERIC(12,2) DEFAULT 0,
  applicant_id TEXT,
  approver_id TEXT,
  status TEXT NOT NULL DEFAULT 'PENDING',
  comment TEXT,
  linked_chat_channel_id TEXT,
  created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
  updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
  approved_at TIMESTAMP
);

-- 11. 招待コード (invitation_codes)
CREATE TABLE IF NOT EXISTS invitation_codes (
  id TEXT PRIMARY KEY,
  code TEXT UNIQUE NOT NULL,
  created_by_user_id TEXT,
  used_by_user_id TEXT,
  used_for TEXT,
  is_used INTEGER DEFAULT 0,
  expires_at TIMESTAMP,
  created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
);
ALTER TABLE invitation_codes ADD COLUMN IF NOT EXISTS used_for TEXT;

-- 12. 排他編集ロック (editing_locks)
CREATE TABLE IF NOT EXISTS editing_locks (
  resource_type TEXT NOT NULL,
  resource_id TEXT NOT NULL,
  user_id TEXT NOT NULL,
  user_name TEXT NOT NULL,
  acquired_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
  last_accessed TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
  created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
  updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (resource_type, resource_id)
);
-- 既存データベース向けマイグレーション (取得・ハートビート時刻カラム)
ALTER TABLE editing_locks ADD COLUMN IF NOT EXISTS acquired_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP;
ALTER TABLE editing_locks ADD COLUMN IF NOT EXISTS last_accessed TIMESTAMP DEFAULT CURRENT_TIMESTAMP;

-- 12b. フィールドセル値 (facility_cells) ※ facility.model.js の updateCells/getCells が使用
CREATE TABLE IF NOT EXISTS facility_cells (
  cell_id TEXT NOT NULL,
  cell_key TEXT NOT NULL,
  value TEXT,
  updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (cell_id, cell_key)
);
CREATE INDEX IF NOT EXISTS idx_facility_cells_key ON facility_cells(cell_key);

-- 13. 監査ログ (system_audit_logs)
CREATE TABLE IF NOT EXISTS system_audit_logs (
  id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  user_id TEXT,
  action TEXT NOT NULL,
  target TEXT,
  details TEXT,
  ip_address TEXT,
  created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
);
CREATE INDEX IF NOT EXISTS idx_audit_created ON system_audit_logs(created_at DESC);
CREATE INDEX IF NOT EXISTS idx_audit_user ON system_audit_logs(user_id);

-- -------------------------------------------------------------
-- 14. 定期考査（考査マスター・コマ・監督割当・配慮教員）
-- ※ exam.model.js が使用するため PostgreSQL 版で追加定義
-- -------------------------------------------------------------

-- 14a. クラス・科目マスタ
CREATE TABLE IF NOT EXISTS classes (
  id TEXT PRIMARY KEY,
  grade INTEGER NOT NULL,
  class_num INTEGER NOT NULL,
  name TEXT NOT NULL
);

CREATE TABLE IF NOT EXISTS subjects (
  id TEXT PRIMARY KEY,
  name TEXT NOT NULL
);

-- 14b. 考査マスター
CREATE TABLE IF NOT EXISTS exam_masters (
  id TEXT PRIMARY KEY,
  title TEXT NOT NULL,
  start_date TEXT,
  end_date TEXT,
  days_count INTEGER NOT NULL DEFAULT 0,
  daily_slots INTEGER NOT NULL DEFAULT 0,
  is_active BOOLEAN NOT NULL DEFAULT true,
  created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
  updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
);
CREATE INDEX IF NOT EXISTS idx_exam_active ON exam_masters(is_active);

-- 14c. 考査コマ（科目時間割スロット）
CREATE TABLE IF NOT EXISTS exam_slots (
  id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  exam_master_id TEXT NOT NULL,
  day_number INTEGER NOT NULL,
  slot_number INTEGER NOT NULL,
  class_id TEXT NOT NULL,
  subject_id TEXT,
  subject_teacher_id TEXT,
  FOREIGN KEY (exam_master_id) REFERENCES exam_masters(id) ON DELETE CASCADE,
  UNIQUE (exam_master_id, day_number, slot_number, class_id)
);
CREATE INDEX IF NOT EXISTS idx_exam_slots_master ON exam_slots(exam_master_id, day_number, slot_number);
-- 既存 DB へマイグレーション (1クラス1スロット1科目の一意制約。seed の ON CONFLICT に必須)
CREATE UNIQUE INDEX IF NOT EXISTS uniq_exam_slot ON exam_slots(exam_master_id, day_number, slot_number, class_id);

-- 14d. 試験監督割当
CREATE TABLE IF NOT EXISTS exam_proctor_assignments (
  id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  exam_master_id TEXT NOT NULL,
  day_number INTEGER NOT NULL,
  slot_number INTEGER NOT NULL,
  class_id TEXT NOT NULL,
  proctor_teacher_id TEXT,
  FOREIGN KEY (exam_master_id) REFERENCES exam_masters(id) ON DELETE CASCADE,
  UNIQUE (exam_master_id, day_number, slot_number, class_id)
);
CREATE INDEX IF NOT EXISTS idx_exam_proctor_master ON exam_proctor_assignments(exam_master_id, day_number, slot_number);

-- 14e. 監督除外・配慮教員
CREATE TABLE IF NOT EXISTS exam_teacher_exemptions (
  id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  exam_master_id TEXT NOT NULL,
  teacher_id TEXT NOT NULL,
  reason TEXT,
  created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
  FOREIGN KEY (exam_master_id) REFERENCES exam_masters(id) ON DELETE CASCADE,
  UNIQUE (exam_master_id, teacher_id)
);

-- -------------------------------------------------------------
-- 15. 年休等・出張 欠席登録 (absence_records)
-- ダッシュボード「職員室 年休等・出張」表示用。1教員 × 1日 × 1区分 で一意。
-- record_type: 'LEAVE' = 年休等（欠席） / 'TRIP' = 出張
-- -------------------------------------------------------------
CREATE TABLE IF NOT EXISTS absence_records (
  id TEXT PRIMARY KEY,
  user_id TEXT NOT NULL,
  record_date DATE NOT NULL,
  record_type TEXT NOT NULL,
  reason TEXT DEFAULT '',
  recorded_by TEXT NOT NULL,
  recorded_by_name TEXT DEFAULT '',
  created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
  updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
  UNIQUE (user_id, record_date, record_type),
  FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE,
  CONSTRAINT chk_absence_record_type CHECK (record_type IN ('LEAVE', 'TRIP'))
);
CREATE INDEX IF NOT EXISTS idx_absence_date ON absence_records(record_date);
CREATE INDEX IF NOT EXISTS idx_absence_date_type ON absence_records(record_date, record_type);
CREATE INDEX IF NOT EXISTS idx_absence_user ON absence_records(user_id);

