ALTER TABLE exam_subject_plan ADD COLUMN IF NOT EXISTS submit_status TEXT NOT NULL DEFAULT 'PENDING';
ALTER TABLE exam_subject_plan ADD COLUMN IF NOT EXISTS student_count INTEGER;

