-- -------------------------------------------------------------
-- 20. 実施科目の決定 (exam_subject_decisions)
-- 実施科目調査 (exam_subject_plan) とは完全に別データとして保持する。
-- 決定行は調査行を「デフォルト値」として複製し、default_json に調査時の値を保存する。
-- 決定行を編集した後も default_json から「デフォルト値（計画値）」を表示できる。
-- 時間割・教室割・監督割・公表ビューは決定データを正式データとして使用する
-- （決定が存在しない場合は調査プランへフォールバックする）。
-- id / source_plan_id は調査行の ID を共有する（時間割スロットの unit_id 参照を維持する）。
-- -------------------------------------------------------------
CREATE TABLE IF NOT EXISTS exam_subject_decisions (
  id TEXT PRIMARY KEY,
  exam_master_id TEXT NOT NULL,
  source_plan_id TEXT,
  subject_name TEXT NOT NULL,
  subject_short TEXT,
  subject_id TEXT,
  grade INTEGER NOT NULL,
  stream TEXT NOT NULL DEFAULT 'OTHER',
  scope TEXT NOT NULL DEFAULT 'GRADE',
  setter_teacher_id TEXT,
  patrol_teacher_id TEXT,
  duration_slots INTEGER NOT NULL DEFAULT 1,
  duration_minutes INTEGER NOT NULL DEFAULT 50,
  fixed_slot INTEGER,
  shared_slot BOOLEAN NOT NULL DEFAULT false,
  broadcast_slot BOOLEAN NOT NULL DEFAULT false,
  solo_subject BOOLEAN NOT NULL DEFAULT false,
  courses TEXT NOT NULL DEFAULT '[]',
  class_ids TEXT NOT NULL DEFAULT '[]',
  room_id TEXT,
  room_name TEXT,
  request_note TEXT,
  student_count INTEGER,
  notes TEXT,
  submit_status TEXT NOT NULL DEFAULT 'PENDING',
  decision_status TEXT NOT NULL DEFAULT 'PENDING',
  default_json TEXT NOT NULL DEFAULT '{}',
  changed_fields TEXT NOT NULL DEFAULT '[]',
  surveyed_by TEXT,
  surveyed_at TIMESTAMP,
  confirmed_by TEXT,
  confirmed_at TIMESTAMP,
  updated_by TEXT,
  updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
  FOREIGN KEY (exam_master_id) REFERENCES exam_masters(id) ON DELETE CASCADE,
  UNIQUE (exam_master_id, subject_name, grade)
);
CREATE INDEX IF NOT EXISTS idx_subject_decisions_master ON exam_subject_decisions(exam_master_id);
CREATE INDEX IF NOT EXISTS idx_subject_decisions_source ON exam_subject_decisions(source_plan_id);

-- 実施科目の決定フェーズ（DRAFT → SURVEY(教員入力) → DECIDED(教務が確定) → ENDED）
ALTER TABLE exam_phases ADD COLUMN IF NOT EXISTS decision_phase TEXT NOT NULL DEFAULT 'DRAFT';

-- -------------------------------------------------------------
-- 21. 時間割コマ・コマ組み・コマ組みグループ・入れ条件
-- コマ (exam_commands)：時間割セルに入れる表記の単位。実施科目の決定の略称から自動生成し、
--   統合（「家庭情報」）や分割（「数学Ⅲ前」「数学Ⅲ後」）は CUSTOM で作成する。
-- コマ組み (exam_block_shapes)：行=クラス・コース、列=時限の表におけるコマの「形」。
--   cells は [クラス・コース, offset(開始コマからの位置), コマID] の組で、span は連続コマ幅。
-- コマ組みグループ (exam_block_groups)：理系／文系／全員受験／放送 等のグループとグループ制約。
-- 入れ条件 (exam_block_conditions)：コマ組みごとに配置不可能なマスを登録する。
-- -------------------------------------------------------------

-- 21a. 時間割コマ
CREATE TABLE IF NOT EXISTS exam_commands (
  id TEXT PRIMARY KEY,
  exam_master_id TEXT NOT NULL,
  name TEXT NOT NULL,
  kind TEXT NOT NULL DEFAULT 'AUTO',
  members TEXT NOT NULL DEFAULT '[]',
  courses TEXT NOT NULL DEFAULT '[]',
  duration_slots INTEGER NOT NULL DEFAULT 1,
  duration_minutes INTEGER NOT NULL DEFAULT 50,
  stream TEXT NOT NULL DEFAULT 'OTHER',
  auto_created BOOLEAN NOT NULL DEFAULT true,
  notes TEXT,
  created_by TEXT,
  updated_by TEXT,
  created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
  updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
  FOREIGN KEY (exam_master_id) REFERENCES exam_masters(id) ON DELETE CASCADE
);
CREATE INDEX IF NOT EXISTS idx_exam_commands_master ON exam_commands(exam_master_id);
CREATE UNIQUE INDEX IF NOT EXISTS uniq_exam_command_name ON exam_commands (exam_master_id, lower(name));

-- 21b. コマ組み（コマの形）
CREATE TABLE IF NOT EXISTS exam_block_shapes (
  id TEXT PRIMARY KEY,
  exam_master_id TEXT NOT NULL,
  name TEXT NOT NULL,
  cells TEXT NOT NULL DEFAULT '[]',
  rows TEXT NOT NULL DEFAULT '[]',
  span INTEGER NOT NULL DEFAULT 1,
  constraints TEXT NOT NULL DEFAULT '{}',
  auto_created BOOLEAN NOT NULL DEFAULT true,
  notes TEXT,
  created_by TEXT,
  updated_by TEXT,
  created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
  updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
  FOREIGN KEY (exam_master_id) REFERENCES exam_masters(id) ON DELETE CASCADE
);
CREATE INDEX IF NOT EXISTS idx_exam_block_shapes_master ON exam_block_shapes(exam_master_id);
CREATE UNIQUE INDEX IF NOT EXISTS uniq_exam_block_shape_name ON exam_block_shapes (exam_master_id, lower(name));

-- 21c. コマ組みグループ
CREATE TABLE IF NOT EXISTS exam_block_groups (
  id TEXT PRIMARY KEY,
  exam_master_id TEXT NOT NULL,
  name TEXT NOT NULL,
  kind TEXT NOT NULL DEFAULT 'CUSTOM',
  members TEXT NOT NULL DEFAULT '[]',
  constraints TEXT NOT NULL DEFAULT '{}',
  notes TEXT,
  created_by TEXT,
  updated_by TEXT,
  created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
  updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
  FOREIGN KEY (exam_master_id) REFERENCES exam_masters(id) ON DELETE CASCADE
);
CREATE INDEX IF NOT EXISTS idx_exam_block_groups_master ON exam_block_groups(exam_master_id);
CREATE UNIQUE INDEX IF NOT EXISTS uniq_exam_block_group_name ON exam_block_groups (exam_master_id, lower(name));

-- 21d. コマ組み入れ条件（配置不可能マス）
CREATE TABLE IF NOT EXISTS exam_block_conditions (
  id TEXT PRIMARY KEY,
  exam_master_id TEXT NOT NULL,
  block_shape_id TEXT NOT NULL,
  class_course_id TEXT,
  day_number INTEGER NOT NULL,
  slot_number INTEGER NOT NULL,
  allowed BOOLEAN NOT NULL DEFAULT false,
  created_by TEXT,
  updated_by TEXT,
  created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
  updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
  FOREIGN KEY (exam_master_id) REFERENCES exam_masters(id) ON DELETE CASCADE,
  UNIQUE (exam_master_id, block_shape_id, day_number, slot_number, class_course_id)
);
CREATE INDEX IF NOT EXISTS idx_exam_block_conditions_master ON exam_block_conditions(exam_master_id, block_shape_id);

-- 21e. 時間割スロットへのコマ・コマ組み参照
ALTER TABLE exam_slots ADD COLUMN IF NOT EXISTS command_id TEXT;
ALTER TABLE exam_slots ADD COLUMN IF NOT EXISTS block_shape_id TEXT;



-- ==========================================
-- 22. メール接続設定 (mail_accounts) ※ mail.model.js / mail.service.js が使用
-- ※ パスワードは AES-256-GCM 暗号文 (iv:tag:base64) で保存し、平文では保存しない
-- ==========================================
CREATE TABLE IF NOT EXISTS mail_accounts (
  id TEXT PRIMARY KEY,
  user_id TEXT NOT NULL UNIQUE,
  email_address TEXT NOT NULL,
  password_enc TEXT NOT NULL,
  imap_host TEXT,
  imap_port INTEGER,
  smtp_host TEXT,
  smtp_port INTEGER,
  status TEXT NOT NULL DEFAULT 'UNVERIFIED',
  last_checked_at TIMESTAMP,
  created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
  updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
  FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE
);

CREATE INDEX IF NOT EXISTS idx_mail_accounts_user ON mail_accounts(user_id);

-- ==========================================
-- 23. メッセージ受信箱 (mail_messages) — mail.model.js / mail.service.js 用
-- 件名と日時を一覧化し、本文 (body) を詳細ペインへ表示する
-- ==========================================
CREATE TABLE IF NOT EXISTS mail_messages (
  id TEXT PRIMARY KEY,
  user_id TEXT NOT NULL,
  sender_name TEXT NOT NULL,
  sender_email TEXT NOT NULL,
  subject TEXT NOT NULL,
  body TEXT NOT NULL,
  is_read INTEGER DEFAULT 0,
  received_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
  FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE
);

CREATE INDEX IF NOT EXISTS idx_mail_messages_user_time ON mail_messages(user_id, received_at DESC);
CREATE INDEX IF NOT EXISTS idx_mail_messages_unread ON mail_messages(user_id, is_read);

